CREATE OR REPLACE FUNCTION public.create_workspace_relationship_property(p_collection_id uuid, p_name text, p_target text, p_target_collection_id uuid, p_many boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_name text := left(btrim(coalesce(p_name, '')), 100);
  v_property public.workspace_collection_properties%rowtype;
begin
  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  select c.project_id into v_project_id
    from public.workspace_collections c
    join public.projects p on p.id = c.project_id
   where c.id = p_collection_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Collection not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  if v_name = '' then
    return jsonb_build_object('status', 'error', 'error', 'A property needs a name');
  end if;
  if p_target is null or p_target not in ('entry', 'page', 'scene') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown relationship target');
  end if;
  if p_target = 'entry' then
    if not exists (select 1 from public.workspace_collections c
                    where c.id = p_target_collection_id and c.project_id = v_project_id) then
      return jsonb_build_object('status', 'error', 'error', 'Target collection not found');
    end if;
  elsif p_target_collection_id is not null then
    return jsonb_build_object('status', 'error', 'error', 'Only an Entry relationship names a collection');
  end if;
  if exists (select 1 from public.workspace_collection_properties p
              where p.collection_id = p_collection_id and lower(p.name) = lower(v_name)) then
    return jsonb_build_object('status', 'error', 'error', 'A property with this name already exists');
  end if;

  insert into public.workspace_collection_properties
    (collection_id, project_id, name, type, position, shown_in_list, relation_target, relation_collection_id, relation_many)
  select p_collection_id, v_project_id, v_name, 'relationship',
         coalesce(max(p.position), 0) + 1,
         count(*) filter (where p.shown_in_list) < 3,
         p_target, p_target_collection_id, coalesce(p_many, true)
    from public.workspace_collection_properties p
   where p.collection_id = p_collection_id
  returning * into v_property;

  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_property));
end;
$function$;

CREATE OR REPLACE FUNCTION public.default_workspace_view_config(p_collection_id uuid, p_type text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'properties', case p_type
      when 'board' then '[]'::jsonb
      else coalesce((
        select jsonb_agg(to_jsonb(p.id::text) order by p.position)
          from public.workspace_collection_properties p
         where p.collection_id = p_collection_id
           and (p_type = 'table' or p.position <= 3)), '[]'::jsonb)
    end,
    'sort', 'null'::jsonb,
    'filters', '[]'::jsonb,
    'group_by', case p_type
      when 'board' then coalesce((
        select to_jsonb(p.id::text)
          from public.workspace_collection_properties p
         where p.collection_id = p_collection_id and p.type in ('status', 'select')
         order by (p.type = 'status') desc, p.position
         limit 1), 'null'::jsonb)
      else 'null'::jsonb
    end);
$function$;

CREATE OR REPLACE FUNCTION public.delete_chapter(p_chapter_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_chapter public.chapters%rowtype;
  v_scene_ids uuid[];
  v_base int;
begin
  perform public.lock_account_word_budget();

  -- RLS: another writer's Chapter is invisible.
  select * into v_chapter from public.chapters c where c.id = p_chapter_id for update;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  select coalesce(array_agg(s.id order by s.position, s.id), '{}')
    into v_scene_ids
    from (select sc.id, sc.position from public.scenes sc
           where sc.chapter_id = p_chapter_id for update) s;

  select coalesce(max(s.position) + 1, 0) into v_base
    from public.scenes s
   where s.manuscript_id = v_chapter.manuscript_id and s.chapter_id is null;

  -- Same rows, new placement. scenes_refresh_project_word_count takes their
  -- words out of the ordered total.
  update public.scenes s
     set chapter_id = null, position = v_base + o.ord::int - 1
    from unnest(v_scene_ids) with ordinality as o(id, ord)
   where s.id = o.id;

  delete from public.chapters c where c.id = p_chapter_id;

  return jsonb_build_object('status', 'ok', 'unplaced_scene_ids', to_jsonb(v_scene_ids));
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_manuscript_group(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_group public.manuscript_groups%rowtype;
begin
  perform public.lock_account_word_budget();

  select g.* into v_group
    from public.manuscript_groups g
    join public.manuscripts m on m.id = g.manuscript_id
    join public.projects p on p.id = m.project_id
   where g.id = p_group_id and p.user_id = auth.uid()
     for update of g;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Group not found');
  end if;

  if exists (select 1 from public.manuscript_groups g where g.parent_group_id = p_group_id)
     or exists (select 1 from public.chapters c where c.group_id = p_group_id) then
    return jsonb_build_object('status', 'error', 'error', 'Only an empty Group can be deleted');
  end if;

  delete from public.manuscript_groups g where g.id = p_group_id;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_collection(p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_parent uuid;
begin
  select c.project_id into v_project_id
    from public.workspace_collections c
    join public.projects p on p.id = c.project_id
   where c.id = p_collection_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Collection not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  -- Only an empty Collection: there is no Trash, so no Entry is ever lost.
  if exists (select 1 from public.workspace_collection_entries e where e.collection_id = p_collection_id) then
    return jsonb_build_object('status', 'error', 'error', 'Only an empty collection can be deleted');
  end if;

  select n.parent_node_id into v_parent from public.workspace_nodes n where n.collection_id = p_collection_id;
  -- Its node goes with it (workspace_nodes_collection_same_project_fkey).
  delete from public.workspace_collections c where c.id = p_collection_id;
  perform public.renumber_workspace_siblings(v_project_id, v_parent);
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_collection_property(p_property_id uuid, p_expected_values integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_property public.workspace_collection_properties%rowtype;
  v_values integer;
begin
  select pr.* into v_property
    from public.workspace_collection_properties pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_property.project_id);

  if v_property.type = 'relationship' then
    select count(distinct r.source_entry_id) into v_values from public.object_references r where r.property_id = p_property_id;
  else
    select count(*) into v_values from public.workspace_entry_values v where v.property_id = p_property_id;
  end if;
  if v_values is distinct from coalesce(p_expected_values, 0) then
    return jsonb_build_object('status', 'confirm', 'values', v_values);
  end if;

  -- Its values go with it (workspace_entry_values_property_same_collection_fkey,
  -- object_references_property_id_fkey). The objects they pointed to stay.
  delete from public.workspace_collection_properties p where p.id = p_property_id;
  update public.workspace_collection_properties p
     set position = r.rank
    from (select id, row_number() over (order by position) as rank
            from public.workspace_collection_properties
           where collection_id = v_property.collection_id) r
   where p.id = r.id and p.position <> r.rank;
  return jsonb_build_object('status', 'ok', 'deleted_values', v_values);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_collection_view(p_view_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_view public.workspace_collection_views%rowtype;
begin
  select v.* into v_view
    from public.workspace_collection_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_view.project_id);

  if not exists (select 1 from public.workspace_collection_views v
                  where v.collection_id = v_view.collection_id and v.id <> p_view_id) then
    return jsonb_build_object('status', 'error', 'error', 'A collection keeps at least one view');
  end if;

  delete from public.workspace_collection_views v where v.id = p_view_id;
  update public.workspace_collection_views v
     set position = r.rank
    from (select id, row_number() over (order by position) as rank
            from public.workspace_collection_views
           where collection_id = v_view.collection_id) r
   where v.id = r.id and v.position <> r.rank;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_folder(p_folder_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_node public.workspace_nodes%rowtype;
begin
  select f.project_id into v_project_id
    from public.workspace_folders f
    join public.projects p on p.id = f.project_id
   where f.id = p_folder_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Folder not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  select n.* into v_node from public.workspace_nodes n where n.folder_id = p_folder_id;
  if exists (select 1 from public.workspace_nodes n where n.parent_node_id = v_node.id) then
    return jsonb_build_object('status', 'error', 'error', 'Only an empty folder can be deleted');
  end if;

  -- Its node goes with it (workspace_nodes_folder_same_project_fkey).
  delete from public.workspace_folders f where f.id = p_folder_id;
  perform public.renumber_workspace_siblings(v_project_id, v_node.parent_node_id);
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.detach_scene_writing_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  r public.writing_sessions%rowtype;
  v_bucket_id uuid;
begin
  select m.project_id into v_project_id
    from public.manuscripts m where m.id = old.manuscript_id;
  if v_project_id is null then
    -- The Project is being deleted: its writing history goes with it.
    delete from public.writing_sessions ws where ws.scene_id = old.id;
    return old;
  end if;

  for r in select * from public.writing_sessions ws where ws.scene_id = old.id for update loop
    select ws.id into v_bucket_id
      from public.writing_sessions ws
     where ws.user_id = r.user_id and ws.session_date = r.session_date
       and ws.scene_id is null and ws.project_id = coalesce(r.project_id, v_project_id)
       for update;
    if found then
      update public.writing_sessions ws set words_added = ws.words_added + r.words_added where ws.id = v_bucket_id;
      delete from public.writing_sessions ws where ws.id = r.id;
    else
      update public.writing_sessions ws
         set scene_id = null, project_id = coalesce(r.project_id, v_project_id)
       where ws.id = r.id;
    end if;
  end loop;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION public.duplicate_project_checked(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source public.projects%rowtype;
  v_source_manuscript_id uuid;
  v_source_chapter record;
  v_new_project public.projects%rowtype;
  v_new_manuscript_id uuid;
  v_new_chapter_id uuid;
  v_group_map jsonb;
  v_new_title text;
  v_used_numbers int[];
  v_draft_num int;
  v_source_total int;
  v_placed_total int;
  v_account_total int;
  v_limit int;
begin
  perform public.lock_account_word_budget();

  select * into v_source
    from public.projects
   where id = p_project_id and user_id = auth.uid();

  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Project not found');
  end if;

  select m.id into v_source_manuscript_id
    from public.manuscripts m
   where m.project_id = p_project_id;

  select coalesce(sum(s.word_count), 0),
         coalesce(sum(s.word_count) filter (where s.chapter_id is not null), 0)
    into v_source_total, v_placed_total
    from public.scenes s
   where s.manuscript_id = v_source_manuscript_id;

  if v_source_total > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_account_total := public.account_word_total();
      if v_account_total + v_source_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  -- Unique "— Draft N" title: smallest unused number starting at 2 (gap-filling).
  select array_agg((regexp_match(p.title, '— Draft (\d+)$'))[1]::int)
    into v_used_numbers
  from public.projects p
  where p.user_id = auth.uid()
    and p.title ilike v_source.title || ' — Draft%'
    and regexp_match(p.title, '— Draft (\d+)$') is not null;

  v_draft_num := 2;
  while v_used_numbers is not null and v_draft_num = any(v_used_numbers) loop
    v_draft_num := v_draft_num + 1;
  end loop;

  v_new_title := v_source.title || ' — Draft ' || v_draft_num;

  insert into public.projects (user_id, title, description, cover_color, word_count)
  values (auth.uid(), v_new_title, v_source.description, v_source.cover_color, v_placed_total)
  returning * into v_new_project;

  -- Created by trg_project_manuscript.
  select m.id into v_new_manuscript_id
    from public.manuscripts m
   where m.project_id = v_new_project.id;

  -- Every Group in one statement (a parent's foreign key is checked at its end).
  select coalesce(jsonb_object_agg(g.id, gen_random_uuid()), '{}'::jsonb) into v_group_map
    from public.manuscript_groups g
   where g.manuscript_id = v_source_manuscript_id;

  insert into public.manuscript_groups (id, manuscript_id, parent_group_id, title, position)
  select (v_group_map ->> g.id::text)::uuid, v_new_manuscript_id,
         (v_group_map ->> g.parent_group_id::text)::uuid, g.title, g.position
    from public.manuscript_groups g
   where g.manuscript_id = v_source_manuscript_id;

  for v_source_chapter in
    select * from public.chapters where manuscript_id = v_source_manuscript_id order by position
  loop
    insert into public.chapters (manuscript_id, group_id, title, position)
    values (v_new_manuscript_id, (v_group_map ->> v_source_chapter.group_id::text)::uuid,
            v_source_chapter.title, v_source_chapter.position)
    returning id into v_new_chapter_id;

    insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
    select v_new_manuscript_id, v_new_chapter_id, s.title, s.content, s.word_count, s.position
      from public.scenes s
     where s.chapter_id = v_source_chapter.id
     order by s.position;
  end loop;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  select v_new_manuscript_id, null, s.title, s.content, s.word_count, s.position
    from public.scenes s
   where s.manuscript_id = v_source_manuscript_id and s.chapter_id is null
   order by s.position;

  return jsonb_build_object('status', 'ok', 'project', to_jsonb(v_new_project));
end;
$function$;

CREATE OR REPLACE FUNCTION public.fill_scene_manuscript_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.manuscript_id is null and new.chapter_id is not null then
    select c.manuscript_id into new.manuscript_id
      from public.chapters c
     where c.id = new.chapter_id;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.forbid_manuscript_group_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.parent_group_id is not null and exists (
       with recursive up(id) as (
         select new.parent_group_id
         union
         select g.parent_group_id
           from public.manuscript_groups g
           join up on g.id = up.id
          where g.parent_group_id is not null)
       select 1 from up where up.id = new.id) then
    raise exception 'A Group cannot be placed inside itself or one of its own Groups'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.forbid_manuscript_reassignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.manuscript_id is distinct from old.manuscript_id then
    raise exception 'A row of % cannot move to another Manuscript', tg_table_name
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.forbid_project_reassignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.project_id is distinct from old.project_id then
    raise exception 'A row of % cannot move to another Project', tg_table_name
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.free_word_limit_for_caller()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_tier text;
  v_cohort text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select subscription_tier into v_tier from public.profiles where id = auth.uid();
  if coalesce(v_tier, 'free') <> 'free' then
    return null;
  end if;

  select coalesce(pricing_cohort, 'starter_2k') into v_cohort
    from public.user_pricing_entitlements where user_id = auth.uid();

  return case coalesce(v_cohort, 'starter_2k')
    when 'legacy_15k' then 15000
    else 2000
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.freeze_workspace_entry_collection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.collection_id is distinct from old.collection_id then
    raise exception 'An Entry cannot move to another Collection'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.freeze_workspace_node_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.target_type is distinct from old.target_type
     or new.document_id is distinct from old.document_id
     or new.folder_id is distinct from old.folder_id
     or new.collection_id is distinct from old.collection_id then
    raise exception 'A Workspace node keeps its object for life'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.profiles (
    id,
    display_name,
    avatar_url,
    xp,
    level,
    has_written_first_words,
    subscription_tier
  ) values (
    new.id,
    new.raw_user_meta_data ->> 'display_name',
    new.raw_user_meta_data ->> 'avatar_url',
    0,
    1,
    false,
    'free'
  );

  insert into public.user_pricing_entitlements (
    user_id,
    pricing_cohort,
    founder_offer_status
  ) values (
    new.id,
    'starter_2k',
    'not_offered'
  );

  return new;
end;
$function$;

-- Unused by the app. SECURITY DEFINER without a pinned search_path, trusts
-- p_user_id, and is executable by PUBLIC/anon. Carried over from the Rune 1.x
-- baseline as-is; hardening is a separate, explicitly approved change.
CREATE OR REPLACE FUNCTION public.increment_game_ticket(p_user_id uuid, p_week_start date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  INSERT INTO public.game_tickets (user_id, week_start, tickets_used)
  VALUES (p_user_id, p_week_start, 1)
  ON CONFLICT (user_id, week_start)
  DO UPDATE SET tickets_used = game_tickets.tickets_used + 1;
END;
$function$;

CREATE OR REPLACE FUNCTION public.increment_scene_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.version = old.version + 1;
  new.updated_at = now(); -- server-side high-precision timestamp
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.insert_scene_checked(p_chapter_id uuid, p_title text, p_content jsonb, p_word_count integer, p_position integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_limit int;
  v_new_total int;
  v_position int;
  v_new public.scenes%rowtype;
begin
  perform public.lock_account_word_budget();

  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  select c.manuscript_id into v_manuscript_id
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_chapter_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  if p_word_count > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(null, p_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  -- p_position is ignored (migration 018): always the end of the Chapter.
  select coalesce(max(s.position) + 1, 0) into v_position
    from public.scenes s
   where s.chapter_id = p_chapter_id;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  values (v_manuscript_id, p_chapter_id, p_title, p_content, p_word_count, v_position)
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'id', v_new.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.insert_unplaced_scene_checked(p_manuscript_id uuid, p_title text, p_content jsonb, p_word_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit int;
  v_new_total int;
  v_position int;
  v_new public.scenes%rowtype;
begin
  perform public.lock_account_word_budget();

  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  if not exists (
    select 1 from public.manuscripts m
      join public.projects p on p.id = m.project_id
     where m.id = p_manuscript_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;

  if p_word_count > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(null, p_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  select coalesce(max(s.position) + 1, 0) into v_position
    from public.scenes s
   where s.manuscript_id = p_manuscript_id and s.chapter_id is null;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  values (p_manuscript_id, null, p_title, p_content, p_word_count, v_position)
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'id', v_new.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.lock_account_word_budget()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  perform pg_advisory_xact_lock(('x' || substr(md5(auth.uid()::text), 1, 16))::bit(64)::bigint);
end;
$function$;

CREATE OR REPLACE FUNCTION public.lock_project_workspace(p_project_id uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select pg_advisory_xact_lock(('x' || substr(md5('rune.workspace:' || p_project_id::text), 1, 16))::bit(64)::bigint);
$function$;

CREATE OR REPLACE FUNCTION public.move_chapter(p_chapter_id uuid, p_parent_group_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chapter public.chapters%rowtype;
  v_parent_manuscript_id uuid;
begin
  perform public.lock_account_word_budget();

  select c.* into v_chapter
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_chapter_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  if p_parent_group_id is not null then
    select g.manuscript_id into v_parent_manuscript_id
      from public.manuscript_groups g
      join public.manuscripts m on m.id = g.manuscript_id
      join public.projects p on p.id = m.project_id
     where g.id = p_parent_group_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Group not found');
    end if;
    if v_parent_manuscript_id <> v_chapter.manuscript_id then
      return jsonb_build_object('status', 'error', 'error', 'A Chapter can only move within its own manuscript');
    end if;
  end if;

  return jsonb_build_object('status', 'ok', 'moved',
    public.place_in_manuscript_structure(v_chapter.manuscript_id, p_parent_group_id, 'chapter', p_chapter_id, p_index));
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_manuscript_group(p_group_id uuid, p_parent_group_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_group public.manuscript_groups%rowtype;
  v_parent_manuscript_id uuid;
begin
  perform public.lock_account_word_budget();

  select g.* into v_group
    from public.manuscript_groups g
    join public.manuscripts m on m.id = g.manuscript_id
    join public.projects p on p.id = m.project_id
   where g.id = p_group_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Group not found');
  end if;

  if p_parent_group_id is not null then
    select g.manuscript_id into v_parent_manuscript_id
      from public.manuscript_groups g
      join public.manuscripts m on m.id = g.manuscript_id
      join public.projects p on p.id = m.project_id
     where g.id = p_parent_group_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Group not found');
    end if;
    if v_parent_manuscript_id <> v_group.manuscript_id then
      return jsonb_build_object('status', 'error', 'error', 'A Group can only move within its own manuscript');
    end if;
    if exists (
         with recursive up(id) as (
           select p_parent_group_id
           union
           select g.parent_group_id from public.manuscript_groups g join up on g.id = up.id
            where g.parent_group_id is not null)
         select 1 from up where up.id = p_group_id) then
      return jsonb_build_object('status', 'error', 'error', 'A Group cannot move inside itself');
    end if;
  end if;

  return jsonb_build_object('status', 'ok', 'moved',
    public.place_in_manuscript_structure(v_group.manuscript_id, p_parent_group_id, 'group', p_group_id, p_index));
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_scene(p_scene_id uuid, p_chapter_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_scene public.scenes%rowtype;
  v_chapter_manuscript_id uuid;
  v_position int;
begin
  perform public.lock_account_word_budget();

  -- RLS: another writer's Scene is invisible.
  select * into v_scene from public.scenes s where s.id = p_scene_id for update;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;

  if p_chapter_id is not null then
    -- RLS: another writer's Chapter is invisible.
    select c.manuscript_id into v_chapter_manuscript_id
      from public.chapters c where c.id = p_chapter_id;
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
    end if;
    if v_chapter_manuscript_id <> v_scene.manuscript_id then
      return jsonb_build_object('status', 'error', 'error', 'A Scene can only move within its own manuscript');
    end if;
  end if;

  if v_scene.chapter_id is not distinct from p_chapter_id then
    return jsonb_build_object('status', 'ok', 'moved', false);
  end if;

  if p_chapter_id is null then
    select coalesce(max(s.position) + 1, 0) into v_position
      from public.scenes s
     where s.manuscript_id = v_scene.manuscript_id and s.chapter_id is null;
  else
    select coalesce(max(s.position) + 1, 0) into v_position
      from public.scenes s
     where s.chapter_id = p_chapter_id;
  end if;

  -- scenes_refresh_project_word_count recomputes projects.word_count.
  update public.scenes
     set chapter_id = p_chapter_id, position = v_position
   where id = p_scene_id;

  if p_chapter_id is not null then
    update public.chapters set updated_at = now() where id = p_chapter_id;
  end if;

  return jsonb_build_object('status', 'ok', 'moved', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_workspace_collection_property(p_property_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_property public.workspace_collection_properties%rowtype;
  v_count integer;
  v_target integer;
begin
  select pr.* into v_property
    from public.workspace_collection_properties pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_property.project_id);

  select count(*) into v_count from public.workspace_collection_properties p where p.collection_id = v_property.collection_id;
  v_target := greatest(0, least(coalesce(p_index, v_count - 1), v_count - 1)) + 1;

  -- One statement: the others close up around the moved one (position is
  -- unique, checked at commit).
  update public.workspace_collection_properties p
     set position = o.next
    from (
      select id, row_number() over (order by (id = p_property_id), position) as rank
        from public.workspace_collection_properties
       where collection_id = v_property.collection_id
    ) r
    cross join lateral (
      select case
               when r.id = p_property_id then v_target
               when r.rank < v_target then r.rank
               else r.rank + 1
             end as next
    ) o
   where p.id = r.id and p.position <> o.next;

  select * into v_property from public.workspace_collection_properties where id = p_property_id;
  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_property));
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_workspace_collection_view(p_view_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_view public.workspace_collection_views%rowtype;
  v_count integer;
  v_target integer;
begin
  select v.* into v_view
    from public.workspace_collection_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_view.project_id);

  select count(*) into v_count from public.workspace_collection_views v where v.collection_id = v_view.collection_id;
  v_target := greatest(0, least(coalesce(p_index, v_count - 1), v_count - 1)) + 1;

  -- One statement: the others close up around the moved one (position is
  -- unique, checked at commit).
  update public.workspace_collection_views v
     set position = o.next
    from (
      select id, row_number() over (order by (id = p_view_id), position) as rank
        from public.workspace_collection_views
       where collection_id = v_view.collection_id
    ) r
    cross join lateral (
      select case
               when r.id = p_view_id then v_target
               when r.rank < v_target then r.rank
               else r.rank + 1
             end as next
    ) o
   where v.id = r.id and v.position <> o.next;

  select * into v_view from public.workspace_collection_views where id = p_view_id;
  return jsonb_build_object('status', 'ok', 'view', to_jsonb(v_view));
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_workspace_node(p_node_id uuid, p_parent_node_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_parent public.workspace_nodes%rowtype;
begin
  select n.project_id into v_project_id
    from public.workspace_nodes n
    join public.projects p on p.id = n.project_id
   where n.id = p_node_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  if p_parent_node_id is not null then
    select n.* into v_parent
      from public.workspace_nodes n
      join public.projects p on p.id = n.project_id
     where n.id = p_parent_node_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Folder not found');
    end if;
    if v_parent.project_id <> v_project_id then
      return jsonb_build_object('status', 'error', 'error', 'Items can only move within their own Project');
    end if;
    if v_parent.target_type <> 'folder' then
      return jsonb_build_object('status', 'error', 'error', 'Only a Folder can hold other items');
    end if;
    if exists (
         with recursive up(id) as (
           select p_parent_node_id
           union
           select n.parent_node_id from public.workspace_nodes n join up on n.id = up.id
            where n.parent_node_id is not null)
         select 1 from up where up.id = p_node_id) then
      return jsonb_build_object('status', 'error', 'error', 'A Folder cannot move inside itself');
    end if;
  end if;

  return jsonb_build_object('status', 'ok', 'moved',
    public.place_workspace_node(p_node_id, p_parent_node_id, p_index));
end;
$function$;

CREATE OR REPLACE FUNCTION public.next_structure_position(p_manuscript_id uuid, p_parent_group_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(max(s.position), 0) + 1
    from (select g.position from public.manuscript_groups g
           where g.manuscript_id = p_manuscript_id and g.parent_group_id is not distinct from p_parent_group_id
          union all
          select c.position from public.chapters c
           where c.manuscript_id = p_manuscript_id and c.group_id is not distinct from p_parent_group_id) s;
$function$;

CREATE OR REPLACE FUNCTION public.normalize_workspace_view_config(p_config jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'properties', coalesce(p_config -> 'properties', '[]'::jsonb),
    'sort',       coalesce(p_config -> 'sort', 'null'::jsonb),
    'filters',    coalesce(p_config -> 'filters', '[]'::jsonb),
    'group_by',   coalesce(p_config -> 'group_by', 'null'::jsonb));
$function$;

-- The ordered manuscript total: every placed Scene of the Manuscript. Unplaced
-- Scenes excluded. The one SQL definition; projects.word_count stores it.
CREATE OR REPLACE FUNCTION public.ordered_manuscript_word_total(p_manuscript_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(sum(s.word_count), 0)::int
    from public.scenes s
   where s.manuscript_id = p_manuscript_id and s.chapter_id is not null;
$function$;

CREATE OR REPLACE FUNCTION public.place_in_manuscript_structure(p_manuscript_id uuid, p_parent_group_id uuid, p_kind text, p_id uuid, p_index integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_kinds text[];
  v_ids uuid[];
  v_n int;
  v_i int;
  v_base int;
  v_changed int := 0;
  v_rows int;
begin
  select coalesce(array_agg(s.kind order by s.position, s.kind desc, s.id), '{}'),
         coalesce(array_agg(s.id order by s.position, s.kind desc, s.id), '{}')
    into v_kinds, v_ids
    from (select 'group'::text as kind, g.id, g.position from public.manuscript_groups g
           where g.manuscript_id = p_manuscript_id and g.parent_group_id is not distinct from p_parent_group_id
             and not (p_kind = 'group' and g.id = p_id)
          union all
          select 'chapter'::text, c.id, c.position from public.chapters c
           where c.manuscript_id = p_manuscript_id and c.group_id is not distinct from p_parent_group_id
             and not (p_kind = 'chapter' and c.id = p_id)) s;

  v_n := coalesce(array_length(v_ids, 1), 0);
  v_i := least(greatest(coalesce(p_index, v_n), 0), v_n);
  v_kinds := v_kinds[1:v_i] || p_kind || v_kinds[v_i + 1:v_n];
  v_ids := v_ids[1:v_i] || p_id || v_ids[v_i + 1:v_n];

  -- Above every position the destination or the moving item holds.
  select greatest(coalesce(max(s.position), 0), 0) + v_n + 2 into v_base
    from (select g.position from public.manuscript_groups g where g.id = any(v_ids)
          union all
          select c.position from public.chapters c where c.id = any(v_ids)) s;

  update public.manuscript_groups g
     set parent_group_id = p_parent_group_id, position = v_base + o.ord::int
    from unnest(v_kinds, v_ids) with ordinality as o(kind, id, ord)
   where o.kind = 'group' and g.id = o.id
     and (g.position <> o.ord or g.parent_group_id is distinct from p_parent_group_id);
  get diagnostics v_rows = row_count;
  v_changed := v_changed + v_rows;

  update public.chapters c
     set group_id = p_parent_group_id, position = v_base + o.ord::int
    from unnest(v_kinds, v_ids) with ordinality as o(kind, id, ord)
   where o.kind = 'chapter' and c.id = o.id
     and (c.position <> o.ord or c.group_id is distinct from p_parent_group_id);
  get diagnostics v_rows = row_count;
  v_changed := v_changed + v_rows;

  if v_changed = 0 then
    return false;
  end if;

  update public.manuscript_groups g
     set position = g.position - v_base
   where g.id = any(v_ids) and g.position > v_base;
  update public.chapters c
     set position = c.position - v_base
   where c.id = any(v_ids) and c.position > v_base;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.place_new_workspace_object()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_type text := case tg_table_name
                   when 'workspace_documents' then 'page'
                   when 'workspace_folders' then 'folder'
                   when 'workspace_collections' then 'collection'
                 end;
begin
  if v_type is null then
    raise exception 'place_new_workspace_object: % is not a Workspace object table', tg_table_name;
  end if;
  perform public.lock_project_workspace(new.project_id);
  insert into public.workspace_nodes (project_id, target_type, document_id, folder_id, collection_id, parent_node_id, position)
  values (new.project_id, v_type,
          case when v_type = 'page' then new.id end,
          case when v_type = 'folder' then new.id end,
          case when v_type = 'collection' then new.id end,
          null,
          (select coalesce(max(n.position), 0) + 1 from public.workspace_nodes n
            where n.project_id = new.project_id and n.parent_node_id is null));
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.place_workspace_node(p_node_id uuid, p_parent_node_id uuid, p_index integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_old_parent uuid;
  v_ids uuid[];
  v_n int;
  v_i int;
  v_changed int;
begin
  select n.project_id, n.parent_node_id into v_project_id, v_old_parent
    from public.workspace_nodes n where n.id = p_node_id;

  select coalesce(array_agg(n.id order by n.position, n.id), '{}') into v_ids
    from public.workspace_nodes n
   where n.project_id = v_project_id
     and n.parent_node_id is not distinct from p_parent_node_id
     and n.id <> p_node_id;

  v_n := coalesce(array_length(v_ids, 1), 0);
  v_i := least(greatest(coalesce(p_index, v_n), 0), v_n);
  v_ids := v_ids[1:v_i] || p_node_id || v_ids[v_i + 1:v_n];

  update public.workspace_nodes n
     set parent_node_id = p_parent_node_id, position = o.ord::int
    from unnest(v_ids) with ordinality as o(id, ord)
   where n.id = o.id
     and (n.position <> o.ord or n.parent_node_id is distinct from p_parent_node_id);
  get diagnostics v_changed = row_count;

  if v_old_parent is distinct from p_parent_node_id then
    perform public.renumber_workspace_siblings(v_project_id, v_old_parent);
  end if;

  return v_changed > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_billing_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.role() = 'authenticated' then
    if new.subscription_tier is distinct from old.subscription_tier then
      new.subscription_tier := old.subscription_tier;
    end if;
    if new.subscription_status is distinct from old.subscription_status then
      new.subscription_status := old.subscription_status;
    end if;
    if new.subscription_price_id is distinct from old.subscription_price_id then
      new.subscription_price_id := old.subscription_price_id;
    end if;
    if new.subscription_period_end is distinct from old.subscription_period_end then
      new.subscription_period_end := old.subscription_period_end;
    end if;
    if new.stripe_customer_id is distinct from old.stripe_customer_id then
      new.stripe_customer_id := old.stripe_customer_id;
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_is_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() = 'authenticated' and new.is_admin is distinct from old.is_admin then
    new.is_admin := old.is_admin;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_project_word_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.word_count is distinct from old.word_count
     and current_user in ('anon', 'authenticated') then
    raise exception 'projects.word_count is maintained by the database'
      using errcode = '42501';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_structure_placement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;
  -- Nested, not AND-ed: each table's record has only its own columns.
  if tg_table_name = 'chapters' then
    if new.group_id is distinct from old.group_id or new.position is distinct from old.position then
      raise exception 'A Chapter''s place in the manuscript changes only through move_chapter'
        using errcode = '42501';
    end if;
  elsif new.parent_group_id is distinct from old.parent_group_id or new.position is distinct from old.position then
    raise exception 'A Group''s place in the manuscript changes only through move_manuscript_group'
      using errcode = '42501';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prune_workspace_view_config(p_collection_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with c as (select public.normalize_workspace_view_config(p_config) as v),
  props as (
    select p.id::text as id, p.type, p.options
      from public.workspace_collection_properties p
     where p.collection_id = p_collection_id
  )
  select jsonb_build_object(
    'properties', coalesce((
        select jsonb_agg(x order by i)
          from c, jsonb_array_elements(c.v -> 'properties') with ordinality as t(x, i)
         where exists (select 1 from props where props.id = x #>> '{}')), '[]'::jsonb),
    'sort', (
        select case
                 when jsonb_typeof(c.v -> 'sort') <> 'object' then 'null'::jsonb
                 when c.v -> 'sort' ->> 'by' = 'title' then c.v -> 'sort'
                 when exists (select 1 from props where props.id = c.v -> 'sort' ->> 'by' and props.type not in ('multi_select', 'relationship'))
                   then c.v -> 'sort'
                 else 'null'::jsonb
               end
          from c),
    'filters', coalesce((
        select jsonb_agg(f order by i)
          from c, jsonb_array_elements(c.v -> 'filters') with ordinality as t(f, i)
         where exists (
                 select 1 from props
                  where props.id = f ->> 'property'
                    and ((f ->> 'op') in ('is_empty', 'is_not_empty')
                         or (props.type in ('select', 'status', 'multi_select')
                             and exists (select 1 from jsonb_array_elements(props.options) o where o -> 'id' = f -> 'value'))))), '[]'::jsonb),
    'group_by', (
        select case
                 when exists (select 1 from props where props.id = c.v ->> 'group_by' and props.type in ('select', 'status'))
                   then c.v -> 'group_by'
                 else 'null'::jsonb
               end
          from c))
  from c;
$function$;

CREATE OR REPLACE FUNCTION public.reference_object_project(p_type text, p_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case p_type
    when 'entry' then (select e.project_id from public.workspace_collection_entries e where e.id = p_id)
    when 'page'  then (select d.project_id from public.workspace_documents d where d.id = p_id)
    when 'scene' then (select m.project_id from public.scenes s join public.manuscripts m on m.id = s.manuscript_id where s.id = p_id)
  end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_project_word_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_project_id uuid;
  v_total int;
begin
  -- Only a change to this row's placed words can change the ordered total.
  if tg_op = 'INSERT' then
    if new.chapter_id is null or new.word_count = 0 then return null; end if;
    v_manuscript_id := new.manuscript_id;
  elsif tg_op = 'DELETE' then
    if old.chapter_id is null or old.word_count = 0 then return null; end if;
    v_manuscript_id := old.manuscript_id;
  else
    if (case when old.chapter_id is null then 0 else old.word_count end)
       = (case when new.chapter_id is null then 0 else new.word_count end) then
      return null;
    end if;
    v_manuscript_id := new.manuscript_id;
  end if;

  select m.project_id into v_project_id
    from public.manuscripts m where m.id = v_manuscript_id;
  if v_project_id is null then return null; end if; -- the Project is being deleted

  -- Lock first; the total is read by the NEXT statement, whose snapshot then
  -- includes every change committed by the previous lock holder.
  perform 1 from public.projects p where p.id = v_project_id for update;
  v_total := public.ordered_manuscript_word_total(v_manuscript_id);

  update public.projects p
     set word_count = v_total
   where p.id = v_project_id and p.word_count <> v_total;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_object_reference(p_reference_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reference public.object_references%rowtype;
begin
  select r.* into v_reference
    from public.object_references r
    join public.projects p on p.id = r.project_id
   where r.id = p_reference_id and p.user_id = auth.uid() and r.property_id is null;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Reference not found');
  end if;
  perform public.lock_project_workspace(v_reference.project_id);
  delete from public.object_references r where r.id = p_reference_id;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.renumber_workspace_siblings(p_project_id uuid, p_parent_node_id uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  update public.workspace_nodes n
     set position = o.ord
    from (select s.id, row_number() over (order by s.position, s.id)::int as ord
            from public.workspace_nodes s
           where s.project_id = p_project_id
             and s.parent_node_id is not distinct from p_parent_node_id) o
   where n.id = o.id and n.position <> o.ord;
$function$;

CREATE OR REPLACE FUNCTION public.reorder_chapter_scenes(p_chapter_id uuid, p_scene_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_current uuid[];
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  -- RLS: another writer's Chapter is invisible.
  if not exists (select 1 from public.chapters c where c.id = p_chapter_id) then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  -- Lock the Chapter's Scenes so a concurrent reorder or move-out waits.
  select coalesce(array_agg(s.id order by s.id), '{}')
    into v_current
    from (select id from public.scenes where chapter_id = p_chapter_id for update) s;

  if coalesce(array_length(p_scene_ids, 1), 0) <> coalesce(array_length(v_current, 1), 0)
     or (select count(distinct x) from unnest(p_scene_ids) x) <> coalesce(array_length(v_current, 1), 0)
     or not (p_scene_ids <@ v_current) then
    return jsonb_build_object('status', 'stale');
  end if;

  update public.scenes s
     set position = o.ord - 1
    from unnest(p_scene_ids) with ordinality as o(id, ord)
   where s.id = o.id
     and s.chapter_id = p_chapter_id
     and s.position is distinct from (o.ord - 1)::int;

  return jsonb_build_object('status', 'ok');
end;
$function$;

-- Save-path RPC. Statuses: ok | word_limit_blocked | version_mismatch | error
-- ('Scene not found'). Once clients depend on it, never overload or extend it.
CREATE OR REPLACE FUNCTION public.save_scene_checked(p_scene_id uuid, p_content jsonb, p_word_count integer, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old_word_count int;
  v_limit int;
  v_new_total int;
  v_updated public.scenes%rowtype;
begin
  perform public.lock_account_word_budget();

  select s.word_count
    into v_old_word_count
    from public.scenes s
    where s.id = p_scene_id;

  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;

  -- Only enforce when words are being added — never block edits/deletions.
  -- A Scene that is already over the allowance is never trapped: shrinking
  -- or net-neutral edits always pass, only further growth is blocked.
  if p_word_count > v_old_word_count then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(p_scene_id, p_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  if p_expected_version is not null then
    update public.scenes
       set content = p_content, word_count = p_word_count
     where id = p_scene_id and version = p_expected_version
     returning * into v_updated;

    if not found then
      return jsonb_build_object('status', 'version_mismatch');
    end if;
  else
    update public.scenes
       set content = p_content, word_count = p_word_count
     where id = p_scene_id
     returning * into v_updated;

    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Scene not found');
    end if;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'updated_at', v_updated.updated_at,
    'version', v_updated.version
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_workspace_entry_relationship(p_entry_id uuid, p_property_id uuid, p_target_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.workspace_collection_entries%rowtype;
  v_property public.workspace_collection_properties%rowtype;
  v_targets uuid[];
  v_bad integer;
begin
  select e.* into v_entry
    from public.workspace_collection_entries e
    join public.projects p on p.id = e.project_id
   where e.id = p_entry_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Entry not found');
  end if;
  perform public.lock_project_workspace(v_entry.project_id);
  select * into v_property from public.workspace_collection_properties pr
   where pr.id = p_property_id and pr.collection_id = v_entry.collection_id and pr.type = 'relationship';
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;

  v_targets := coalesce((select array_agg(t order by i)
                           from (select t, min(i) as i from unnest(coalesce(p_target_ids, '{}')) with ordinality as u(t, i)
                                  where t is not null group by t) d), '{}');
  if cardinality(v_targets) > 1 and not v_property.relation_many then
    return jsonb_build_object('status', 'error', 'error', 'This relationship holds one value');
  end if;
  if cardinality(v_targets) > 500 then
    return jsonb_build_object('status', 'error', 'error', 'Too many values');
  end if;
  if p_entry_id = any (v_targets) then
    return jsonb_build_object('status', 'error', 'error', 'An entry cannot point to itself');
  end if;
  select count(*) into v_bad
    from unnest(v_targets) t
   where case v_property.relation_target
           when 'entry' then not exists (select 1 from public.workspace_collection_entries e
                                          where e.id = t and e.collection_id = v_property.relation_collection_id
                                            and e.project_id = v_entry.project_id)
           else public.reference_object_project(v_property.relation_target, t) is distinct from v_entry.project_id
         end;
  if v_bad > 0 then
    return jsonb_build_object('status', 'error', 'error', 'Not a valid target');
  end if;

  delete from public.object_references r
   where r.property_id = p_property_id and r.source_entry_id = p_entry_id
     and not (coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = any (v_targets));
  update public.object_references r
     set position = o.ord
    from unnest(v_targets) with ordinality as o(t, ord)
   where r.property_id = p_property_id and r.source_entry_id = p_entry_id
     and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = o.t
     and r.position <> o.ord;
  insert into public.object_references
    (project_id, source_type, source_entry_id, target_type, target_entry_id, target_document_id, target_scene_id, property_id, position)
  select v_entry.project_id, 'entry', p_entry_id, v_property.relation_target,
         case when v_property.relation_target = 'entry' then o.t end,
         case when v_property.relation_target = 'page' then o.t end,
         case when v_property.relation_target = 'scene' then o.t end,
         p_property_id, o.ord
    from unnest(v_targets) with ordinality as o(t, ord)
   where not exists (select 1 from public.object_references r
                      where r.property_id = p_property_id and r.source_entry_id = p_entry_id
                        and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = o.t);

  return jsonb_build_object('status', 'ok', 'targets', to_jsonb(v_targets));
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_workspace_entry_value(p_entry_id uuid, p_property_id uuid, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.workspace_collection_entries%rowtype;
  v_property public.workspace_collection_properties%rowtype;
  v_value jsonb := p_value;
begin
  select e.* into v_entry
    from public.workspace_collection_entries e
    join public.projects p on p.id = e.project_id
   where e.id = p_entry_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Entry not found');
  end if;
  -- Only a property of the Entry's own Collection.
  select * into v_property from public.workspace_collection_properties pr
   where pr.id = p_property_id and pr.collection_id = v_entry.collection_id;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;

  if v_property.type = 'text' and jsonb_typeof(v_value) = 'string' then
    v_value := to_jsonb(btrim(v_value #>> '{}'));
  elsif v_property.type = 'multi_select' and jsonb_typeof(v_value) = 'array' then
    -- Duplicates collapse, first occurrence kept.
    v_value := coalesce((select jsonb_agg(x order by i)
                           from (select x, min(i) as i from jsonb_array_elements(v_value) with ordinality as t(x, i) group by x) d),
                        '[]'::jsonb);
  end if;

  if v_value is null or v_value = 'null'::jsonb or v_value = '""'::jsonb or v_value = '[]'::jsonb or v_value = 'false'::jsonb then
    delete from public.workspace_entry_values v where v.entry_id = p_entry_id and v.property_id = p_property_id;
    return jsonb_build_object('status', 'ok', 'value', null);
  end if;
  if not public.workspace_property_value_valid(v_property.type, v_property.options, v_value) then
    return jsonb_build_object('status', 'error', 'error', 'Invalid value');
  end if;

  insert into public.workspace_entry_values (entry_id, property_id, collection_id, project_id, value)
  values (p_entry_id, p_property_id, v_entry.collection_id, v_entry.project_id, v_value)
  on conflict (entry_id, property_id) do update set value = excluded.value;
  return jsonb_build_object('status', 'ok', 'value', v_value);
end;
$function$;

CREATE OR REPLACE FUNCTION public.stamp_workspace_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.version := 1;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.version := case when new.content is distinct from old.content then old.version + 1 else old.version end;
  new.updated_at := case when new.content is distinct from old.content or new.title is distinct from old.title
                         then now() else old.updated_at end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.stamp_workspace_folder()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.updated_at := case when new.title is distinct from old.title then now() else old.updated_at end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_workspace_views_with_property()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_collection_id uuid := coalesce(new.collection_id, old.collection_id);
begin
  -- The Collection itself is being deleted: its Views go with it.
  if not exists (select 1 from public.workspace_collections c where c.id = v_collection_id) then
    return null;
  end if;

  if tg_op = 'INSERT' then
    update public.workspace_collection_views v
       set config = jsonb_set(v.config, '{properties}', (v.config -> 'properties') || to_jsonb(new.id::text))
     where v.collection_id = v_collection_id
       and (v.type = 'table' or jsonb_array_length(v.config -> 'properties') < 3);
    if new.type in ('select', 'status') then
      update public.workspace_collection_views v
         set config = jsonb_set(v.config, '{group_by}', to_jsonb(new.id::text))
       where v.collection_id = v_collection_id and v.type = 'board' and jsonb_typeof(v.config -> 'group_by') = 'null';
    end if;
    return null;
  end if;

  update public.workspace_collection_views v
     set config = public.prune_workspace_view_config(v_collection_id, v.config)
   where v.collection_id = v_collection_id
     and v.config is distinct from public.prune_workspace_view_config(v_collection_id, v.config);
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.touch_pricing_entitlement_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_workspace_collection_property(p_property_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.workspace_collection_properties%rowtype;
  v_new public.workspace_collection_properties%rowtype;
  v_key text;
  v_opt jsonb;
  v_options jsonb := '[]'::jsonb;
  v_ids text[];
  v_cleared integer := 0;
  v_n integer;
begin
  select pr.* into v_old
    from public.workspace_collection_properties pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  -- Re-read under the lock.
  select * into v_old from public.workspace_collection_properties where id = p_property_id;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('name', 'type', 'options', 'shown_in_list') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'name' then
    if jsonb_typeof(p_changes -> 'name') is distinct from 'string' or btrim(p_changes ->> 'name') = '' then
      return jsonb_build_object('status', 'error', 'error', 'A property needs a name');
    end if;
    v_new.name := left(btrim(p_changes ->> 'name'), 100);
    if exists (select 1 from public.workspace_collection_properties p
                where p.collection_id = v_old.collection_id and p.id <> v_old.id and lower(p.name) = lower(v_new.name)) then
      return jsonb_build_object('status', 'error', 'error', 'A property with this name already exists');
    end if;
  end if;

  if p_changes ? 'shown_in_list' then
    if jsonb_typeof(p_changes -> 'shown_in_list') is distinct from 'boolean' then
      return jsonb_build_object('status', 'error', 'error', 'shown_in_list must be true or false');
    end if;
    v_new.shown_in_list := (p_changes ->> 'shown_in_list')::boolean;
  end if;

  if p_changes ? 'type' then
    v_new.type := p_changes ->> 'type';
    -- Only where every value survives as it is (select ↔ status), or is
    -- wrapped losslessly (a single choice becomes a one-item multi-select).
    if v_new.type is distinct from v_old.type
       and not (v_old.type in ('select', 'status') and v_new.type in ('select', 'status', 'multi_select')) then
      return jsonb_build_object('status', 'error', 'error', 'This property’s type can’t be changed');
    end if;
  end if;

  if p_changes ? 'options' then
    if v_new.type not in ('select', 'multi_select', 'status') then
      return jsonb_build_object('status', 'error', 'error', 'Only a choice property has options');
    end if;
    if jsonb_typeof(p_changes -> 'options') is distinct from 'array' then
      return jsonb_build_object('status', 'error', 'error', 'Invalid property options');
    end if;
    -- An option keeps its id; one without an id is new and gets one here. An
    -- id the property never had is refused (a client can't invent a reference).
    for v_opt in select * from jsonb_array_elements(p_changes -> 'options') loop
      if jsonb_typeof(v_opt) <> 'object' then
        return jsonb_build_object('status', 'error', 'error', 'Invalid property options');
      end if;
      if v_opt ? 'id' and not exists (select 1 from jsonb_array_elements(v_old.options) o where o -> 'id' = v_opt -> 'id') then
        return jsonb_build_object('status', 'error', 'error', 'Unknown option');
      end if;
      v_options := v_options || jsonb_build_array(jsonb_build_object(
        'id', coalesce(v_opt ->> 'id', gen_random_uuid()::text),
        'name', left(btrim(coalesce(v_opt ->> 'name', '')), 100)));
    end loop;
    if not public.workspace_property_options_valid(v_options) then
      return jsonb_build_object('status', 'error', 'error', 'Each option needs a different name');
    end if;
    v_new.options := v_options;
  end if;

  -- Values first, then the definition, so every value is valid against the
  -- options it will have when the statement ends.
  v_ids := array(select o ->> 'id' from jsonb_array_elements(v_new.options) o);
  if v_old.type in ('select', 'status') then
    -- Removed options: those values are cleared.
    delete from public.workspace_entry_values v
     where v.property_id = v_old.id and not ((v.value #>> '{}') = any (v_ids));
    get diagnostics v_cleared = row_count;
  elsif v_old.type = 'multi_select' then
    with stripped as (
      select v.entry_id,
             coalesce((select jsonb_agg(x order by i) from jsonb_array_elements(v.value) with ordinality as t(x, i)
                        where (x #>> '{}') = any (v_ids)), '[]'::jsonb) as value
        from public.workspace_entry_values v
       where v.property_id = v_old.id
    ), changed as (
      select s.* from stripped s
        join public.workspace_entry_values v on v.entry_id = s.entry_id and v.property_id = v_old.id
       where s.value <> v.value
    ), emptied as (
      delete from public.workspace_entry_values v using changed c
       where v.property_id = v_old.id and v.entry_id = c.entry_id and c.value = '[]'::jsonb
      returning 1
    ), narrowed as (
      update public.workspace_entry_values v set value = c.value from changed c
       where v.property_id = v_old.id and v.entry_id = c.entry_id and c.value <> '[]'::jsonb
      returning 1
    )
    select (select count(*) from emptied) + (select count(*) from narrowed) into v_cleared;
  end if;

  update public.workspace_collection_properties
     set name = v_new.name, type = v_new.type, options = v_new.options, shown_in_list = v_new.shown_in_list
   where id = v_old.id
  returning * into v_new;

  if v_old.type in ('select', 'status') and v_new.type = 'multi_select' then
    update public.workspace_entry_values v set value = jsonb_build_array(v.value) where v.property_id = v_old.id;
    get diagnostics v_n = row_count;
  end if;

  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_new), 'cleared', v_cleared);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_workspace_collection_view(p_view_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.workspace_collection_views%rowtype;
  v_new public.workspace_collection_views%rowtype;
  v_key text;
begin
  select v.* into v_old
    from public.workspace_collection_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  -- Re-read under the lock.
  select * into v_old from public.workspace_collection_views where id = p_view_id;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('name', 'type', 'config') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'name' then
    if jsonb_typeof(p_changes -> 'name') is distinct from 'string' or btrim(p_changes ->> 'name') = '' then
      return jsonb_build_object('status', 'error', 'error', 'A view needs a name');
    end if;
    v_new.name := left(btrim(p_changes ->> 'name'), 100);
  end if;

  if p_changes ? 'type' then
    if (p_changes ->> 'type') is null or (p_changes ->> 'type') not in ('list', 'table', 'board') then
      return jsonb_build_object('status', 'error', 'error', 'Unknown view type');
    end if;
    v_new.type := p_changes ->> 'type';
  end if;

  if p_changes ? 'config' then
    if not public.workspace_view_config_shape_valid(p_changes -> 'config') then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
    v_new.config := public.normalize_workspace_view_config(p_changes -> 'config');
    if v_new.config is distinct from public.prune_workspace_view_config(v_old.collection_id, v_new.config) then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
  end if;

  if v_new.type = 'board' and jsonb_typeof(v_new.config -> 'group_by') = 'null' then
    v_new.config := jsonb_set(v_new.config, '{group_by}',
      public.default_workspace_view_config(v_old.collection_id, 'board') -> 'group_by');
  end if;

  update public.workspace_collection_views
     set name = v_new.name, type = v_new.type, config = v_new.config
   where id = v_old.id
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'view', to_jsonb(v_new));
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_workspace_relationship_property(p_property_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.workspace_collection_properties%rowtype;
  v_new public.workspace_collection_properties%rowtype;
  v_key text;
begin
  select pr.* into v_old
    from public.workspace_collection_properties pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid() and pr.type = 'relationship';
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  select * into v_old from public.workspace_collection_properties where id = p_property_id;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('many', 'target', 'target_collection_id') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'many' then
    if jsonb_typeof(p_changes -> 'many') is distinct from 'boolean' then
      return jsonb_build_object('status', 'error', 'error', 'many must be true or false');
    end if;
    v_new.relation_many := (p_changes ->> 'many')::boolean;
    if not v_new.relation_many and exists (
         select 1 from public.object_references r where r.property_id = p_property_id
          group by r.source_entry_id having count(*) > 1) then
      return jsonb_build_object('status', 'error', 'error', 'Some entries hold more than one');
    end if;
  end if;

  if p_changes ? 'target' or p_changes ? 'target_collection_id' then
    v_new.relation_target := coalesce(p_changes ->> 'target', v_old.relation_target);
    v_new.relation_collection_id := case when v_new.relation_target = 'entry'
                                         then coalesce((p_changes ->> 'target_collection_id')::uuid, v_old.relation_collection_id)
                                         else null end;
    if v_new.relation_target not in ('entry', 'page', 'scene') then
      return jsonb_build_object('status', 'error', 'error', 'Unknown relationship target');
    end if;
    if v_new.relation_target = 'entry'
       and not exists (select 1 from public.workspace_collections c
                        where c.id = v_new.relation_collection_id and c.project_id = v_old.project_id) then
      return jsonb_build_object('status', 'error', 'error', 'Target collection not found');
    end if;
    if (v_new.relation_target, v_new.relation_collection_id) is distinct from (v_old.relation_target, v_old.relation_collection_id)
       and exists (select 1 from public.object_references r where r.property_id = p_property_id) then
      return jsonb_build_object('status', 'error', 'error', 'Clear its values before changing what it points to');
    end if;
  end if;

  update public.workspace_collection_properties
     set relation_target = v_new.relation_target,
         relation_collection_id = v_new.relation_collection_id,
         relation_many = v_new.relation_many
   where id = p_property_id
  returning * into v_new;
  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_new));
end;
$function$;

CREATE OR REPLACE FUNCTION public.workspace_property_options_valid(p_options jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_typeof(p_options) = 'array'
     and jsonb_array_length(p_options) <= 200
     and not exists (
           select 1 from jsonb_array_elements(p_options) o
            where jsonb_typeof(o) <> 'object'
               or jsonb_typeof(o -> 'id') is distinct from 'string'
               or jsonb_typeof(o -> 'name') is distinct from 'string'
               or btrim(o ->> 'id') = '' or char_length(o ->> 'id') > 64
               or btrim(o ->> 'name') = '' or o ->> 'name' <> btrim(o ->> 'name')
               or char_length(o ->> 'name') > 100
               or exists (select 1 from jsonb_object_keys(o) k where k not in ('id', 'name')))
     and (select count(distinct o ->> 'id') = count(*) and count(distinct lower(o ->> 'name')) = count(*)
            from jsonb_array_elements(p_options) o);
$function$;

CREATE OR REPLACE FUNCTION public.workspace_property_value_valid(p_type text, p_options jsonb, p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_ids text[] := array(select o ->> 'id' from jsonb_array_elements(coalesce(p_options, '[]'::jsonb)) o);
begin
  case p_type
    when 'text' then
      return jsonb_typeof(p_value) = 'string' and btrim(p_value #>> '{}') <> '' and char_length(p_value #>> '{}') <= 2000;
    when 'number' then
      return jsonb_typeof(p_value) = 'number';
    when 'checkbox' then
      return p_value = 'true'::jsonb;
    when 'select', 'status' then
      return jsonb_typeof(p_value) = 'string' and (p_value #>> '{}') = any (v_ids);
    when 'multi_select' then
      return jsonb_typeof(p_value) = 'array'
         and jsonb_array_length(p_value) > 0
         and not exists (select 1 from jsonb_array_elements(p_value) v
                          where jsonb_typeof(v) <> 'string' or not ((v #>> '{}') = any (v_ids)))
         and (select count(distinct v) = count(*) from jsonb_array_elements(p_value) v);
    when 'date' then
      if jsonb_typeof(p_value) <> 'string' or (p_value #>> '{}') !~ '^\d{4}-\d{2}-\d{2}$' then
        return false;
      end if;
      begin
        return to_char((p_value #>> '{}')::date, 'YYYY-MM-DD') = (p_value #>> '{}');
      exception when others then
        return false;
      end;
    else
      return false;
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION public.workspace_view_config_shape_valid(p_config jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_typeof(p_config) = 'object'
     and not exists (select 1 from jsonb_object_keys(p_config) k where k not in ('properties', 'sort', 'filters', 'group_by'))
     -- properties: distinct strings
     and (not p_config ? 'properties' or (
           jsonb_typeof(p_config -> 'properties') = 'array'
       and jsonb_array_length(p_config -> 'properties') <= 200
       and not exists (select 1 from jsonb_array_elements(p_config -> 'properties') x where jsonb_typeof(x) <> 'string')
       and (select count(distinct x) = count(*) from jsonb_array_elements(p_config -> 'properties') x)))
     -- sort: null or { by, direction }
     and (not p_config ? 'sort' or jsonb_typeof(p_config -> 'sort') = 'null' or (
           jsonb_typeof(p_config -> 'sort') = 'object'
       and not exists (select 1 from jsonb_object_keys(p_config -> 'sort') k where k not in ('by', 'direction'))
       and jsonb_typeof(p_config -> 'sort' -> 'by') = 'string'
       and (p_config -> 'sort' ->> 'direction') in ('asc', 'desc')))
     -- filters: [{ property, op, value? }]
     and (not p_config ? 'filters' or (
           jsonb_typeof(p_config -> 'filters') = 'array'
       and jsonb_array_length(p_config -> 'filters') <= 20
       and not exists (
             select 1 from jsonb_array_elements(p_config -> 'filters') f
              where jsonb_typeof(f) <> 'object'
                 or exists (select 1 from jsonb_object_keys(f) k where k not in ('property', 'op', 'value'))
                 or jsonb_typeof(f -> 'property') is distinct from 'string'
                 or (f ->> 'op') is null
                 or (f ->> 'op') not in ('is', 'is_not', 'is_empty', 'is_not_empty')
                 or ((f ->> 'op') in ('is', 'is_not') and jsonb_typeof(f -> 'value') is distinct from 'string')
                 or ((f ->> 'op') in ('is_empty', 'is_not_empty') and f ? 'value'))))
     -- group_by: null or a string
     and (not p_config ? 'group_by' or jsonb_typeof(p_config -> 'group_by') in ('null', 'string'));
$function$;

